use minisign_verify::{PublicKey, Signature};
use std::{env,fs,io::Read};
fn main() -> Result<(),Box<dyn std::error::Error>> {
 let a:Vec<String>=env::args().collect();
 if a.len()!=4 {return Err("Usage: verifier PUBLIC_KEY SIGNATURE ASSET".into());}
 let key=PublicKey::from_file(&a[1])?;
 let signature=Signature::from_file(&a[2])?;
 match key.verify_stream(&signature) {
  Ok(mut verifier)=>{let mut f=fs::File::open(&a[3])?; let mut b=[0u8;8192];loop{let n=f.read(&mut b)?;if n==0{break;}verifier.update(&b[..n]);}verifier.finalize()?;},
  Err(_)=>key.verify(&fs::read(&a[3])?,&signature,true)?,
 }
 println!("{}",signature.trusted_comment());
 Ok(())
}
